text:
.content-blocking-category {
  border-radius: 4px;
  margin: 3px 0;
  padding: 9px;
  border: 1px solid var(--border-color-box-info);
  background-color: var(--background-color-box-info);

  &.selected {
    border: 1px solid var(--selected-item-color);
    background-color: light-dark(
      color-mix(in srgb, var(--selected-item-color) 5%, transparent),
      color-mix(in srgb, var(--selected-item-color) 10%, transparent)
    );
  }
